import { OPTIONS, mask } from '../';

describe('mask', () => {
  it('should run nothing', () => {
    expect(mask([], 'test')).toEqual('test');
  });

  it('should run number for string', () => {
    expect(mask(['fakeValidator', OPTIONS.number], 'test')).toEqual('');
  });

  it('should run number mixed', () => {
    expect(mask(['fakeValidator', OPTIONS.number], 'te6s7t.5')).toEqual('67.5');
  });

  it('should run integer mixed', () => {
    expect(mask(['fakeValidator', OPTIONS.integer], 'te6s7t.5')).toEqual('675');
  });

  it('should run strictNumber mixed', () => {
    expect(mask(['fakeValidator', OPTIONS.strictNumber], 'te6.7..aa5')).toEqual(
      '6.7',
    );
  });

  it('should run strictInteger mixed', () => {
    expect(mask(['fakeValidator', OPTIONS.strictInteger], '..te67t.5')).toEqual(
      '67',
    );
  });
});
